{"code":"import random

def generate(rng):
    cell=rng.randint(3,7); nr=rng.randint(2,4); nc=rng.randint(2,4)
    H=nr*cell+nr-1; W=nc*cell+nc-1
    g=[[0 for _ in range(W)] for _ in range(H)]
    for r in range(nr-1):
        y=(r+1)*cell+r
        for x in range(W): g[y][x]=7
    for c in range(nc-1):
        x=(c+1)*cell+c
        for y in range(H): g[y][x]=7
    # Motifs are small symmetric marks, with source color 9 and occasional palette variant 8.
    cy=cell//2; cx=cell//2
    motifs=[]
    for kind in range(5):
        pts={(cy,cx)}
        if kind&1 and cy>0: pts.add((cy-1,cx))
        if kind&2 and cy+1<cell: pts.add((cy+1,cx))
        if kind&4 and cx>0: pts.add((cy,cx-1))
        if kind==0 or rng.random()<.7:
            if cx+1<cell: pts.add((cy,cx+1))
        motifs.append(list(pts))
    for band in range(nr):
        motif=rng.choice(motifs)
        for col in range(nc):
            if rng.random()<rng.uniform(.35,.9):
                for p in motif:
                    if rng.random()<rng.uniform(.55,1.0):
                        y=band*(cell+1)+p[0]; x=col*(cell+1)+p[1]
                        if g[y][x]==0: g[y][x]=9
    return g"}

